    {
      "name": "Polynomial.hasseDeriv_coeff",
      "type": " {R : Type u_1} [Semiring R] (k : ℕ) (f : Polynomial R) (n : ℕ) : ((Polynomial.hasseDeriv k) f).coeff n = ↑((n + k).choose k) * f.coeff (n + k)",
      "module": "Mathlib.Algebra.Polynomial.HasseDeriv"
    },
    {
      "name": "Polynomial.hasseDeriv_apply",
      "type": " {R : Type u_1} [Semiring R] (k : ℕ) (f : Polynomial R) : (Polynomial.hasseDeriv k) f = f.sum fun i r => (Polynomial.monomial (i - k)) (↑(i.choose k) * r)",
      "module": "Mathlib.Algebra.Polynomial.HasseDeriv"
    },
    {
      "name": "Polynomial.hasseDeriv_monomial",
      "type": " {R : Type u_1} [Semiring R] (k n : ℕ) (r : R) : (Polynomial.hasseDeriv k) ((Polynomial.monomial n) r) = (Polynomial.monomial (n - k)) (↑(n.choose k) * r)",
      "module": "Mathlib.Algebra.Polynomial.HasseDeriv"
    },
    {
      "name": "Polynomial.hasseDeriv_mul",
      "type": " {R : Type u_1} [Semiring R] (k : ℕ) (f g : Polynomial R) : (Polynomial.hasseDeriv k) (f * g) = ∑ ij ∈ Finset.HasAntidiagonal.antidiagonal k, (Polynomial.hasseDeriv ij.1) f * (Polynomial.hasseDeriv ij.2) g",
      "module": "Mathlib.Algebra.Polynomial.HasseDeriv"
    }
  ]
}

{
  "items": [
    {
      "name": "Polynomial.hasseDeriv_mul",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f g : Polynomial R),\n  (Polynomial.hasseDeriv k) (f * g) =\n    ∑ ij ∈ Finset.antidiagonal k, (Polynomial.hasseDeriv ij.1) f * (Polynomial.hasseDeriv ij.2) g"
    },
    {
      "name": "Polynomial.derivative_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {f g : Polynomial R},\n  Polynomial.derivative (f * g) = Polynomial.derivative f * g + f * Polynomial.derivative g"
    },
    {
      "name": "Polynomial.derivative_prod",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type y} [inst : CommSemiring R] [inst_1 : DecidableEq ι] {s : Multiset ι} {f : ι → Polynomial R},\n  Polynomial.derivative (Multiset.map f s).prod =\n    (Multiset.map (fun i => (Multiset.map f (s.erase i)).prod * Polynomial.derivative (f i)) s).sum"
    },
    {
      "name": "Polynomial.derivative_prod_finset",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type y} [inst : CommSemiring R] [inst_1 : DecidableEq ι] {s : Finset ι} {f : ι → Polynomial R},\n  Polynomial.derivative (∏ b ∈ s, f b) = ∑ a ∈ s, (∏ b ∈ s.erase a, f b) * Polynomial.derivative (f a)"
    },
    {
      "name": "MvPolynomial.pderiv_mul",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} [inst : CommSemiring R] {i : σ} {f g : MvPolynomial σ R},\n  (MvPolynomial.pderiv i) (f * g) = (MvPolynomial.pderiv i) f * g + f * (MvPolynomial.pderiv i) g"
    },
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    }
  ]
}

